{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C44"],
      "claim": "Tranexamic acid, a small zwitterionic cyclohexane carboxylic acid, has an absolute oral bioavailability of 46% in healthy volunteers, directly supporting F ≥20% for a carboxylic acid-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Gabapentin, a cyclohexane amino acid with a carboxylic acid, has an absolute oral bioavailability of ~60% after a 300 mg oral dose versus IV, supporting high F for the query's cyclohexane/carboxylate features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Captopril, a carboxylic acid-containing drug, has an absolute oral bioavailability of about 60% compared with intravenous administration, supporting high F for an acidic, moderately polar drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Cilomilast, a lipophilic carboxylic acid, has a mean absolute oral bioavailability of 96% (range 92–102%) in fasted healthy volunteers, supporting high F for a lipophilic carboxylic acid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Alpha-lipoic acid, a carboxylic acid with limited solubility and extensive first-pass metabolism, still has an oral bioavailability of ~30%, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a carboxylic acid-containing, moderately lipophilic molecule with cyclohexyl and amide features. High-transfer experimental analogues—tranexamic acid (46%), gabapentin (~60%), captopril (~60%), cilomilast (96%), and alpha-lipoic acid (~30%)—all show absolute oral bioavailability above the 20% threshold. No affirmative evidence supports F<20%, so the prediction is high.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule.",
    "No data on solubility, permeability, first-pass metabolism, or transporter-mediated absorption for the query.",
    "Extrapolation relies on analogues with high transfer scores but not identical structures."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

